static int drm_mmap_dma ( struct file * filp , struct vm_area_struct * vma ) { struct drm_file * priv = filp -> private_data ; struct drm_device * dev ; struct drm_device_dma * dma ; unsigned long length = vma -> vm_end - vma -> vm_start ; dev = priv -> minor -> dev ; dma = dev -> dma ; DRM_DEBUG ( "start = 0x%lx, end = 0x%lx, page offset = 0x%lx\n" , vma -> vm_start , vma -> vm_end , vma -> vm_pgoff ) ; if ( ! dma || ( length >> PAGE_SHIFT ) != dma -> page_count ) { return - EINVAL ; } if ( ! capable ( CAP_SYS_ADMIN ) && ( dma -> flags & _DRM_DMA_USE_PCI_RO ) ) { vma -> vm_flags &= ~ ( VM_WRITE | VM_MAYWRITE ) ; vma -> vm_page_prot = __pgprot ( pte_val ( pte_wrprotect ( __pte ( pgprot_val ( vma -> vm_page_prot ) ) ) ) ) ; } vma -> vm_ops = & drm_vm_dma_ops ; vma -> vm_flags |= VM_DONTEXPAND | VM_DONTDUMP ; drm_vm_open_locked ( dev , vma ) ; return 0 ; } 